query:
-- Delete teams that have no players (the old duplicates)
DELETE FROM teams WHERE id NOT IN (
  SELECT DISTINCT teamId FROM players
) AND name IN (
  'الاتحاد بنغازي', 'الثورة الزاوية', 'الجيش طرابلس', 'الشرطة طرابلس', 
  'الفيصلي الزاوية', 'النصر الزاوية', 'الهلال البيضاوي', 'الوحدة سرت'
);

-- Verify final teams
SELECT id, name, city FROM teams ORDER BY name;

-- Final verification of players by team
SELECT t.name, COUNT(p.id) as player_count 
FROM teams t 
LEFT JOIN players p ON t.id = p.teamId 
GROUP BY t.name 
ORDER BY t.name;

